head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


frame.SetEvent("onwinstat", OnWinStat);
iTimer = 0;
maxval = 0;
gOldWidthSize = frame.width;
gNewWidthSize = 0;
array_grid = new Array();
padding_left = 10;
/**
 * @method
 * @name OnSized
 * @description desc
 * @param {string} winID desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    //gNewHeightSize = frame.height;
    scwin.GauceObjResize(frame.width, frame.height);
};
/**
 * @method
 * @name OnSizedMax
 * @description desc
 * @param {string} winID desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    //alert(frame.width);
    scwin.GauceObjResize($c.frame.path("/").width - 10, frame.height);
};
/**
 * @method
 * @name OnWinStat
 * @description desc
 * @param {string} winID desc
 * @param {string} statmsg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        //frameMain의 함수 호출
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
/**
 * @method
 * @name setResizeGrid
 * @description desc
 * @param {string} grid desc
 * @param {string} padding_size desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setResizeGrid = function(grid, padding_size) {
    scwin.array_grid = grid;
    if (padding_size != undefined) scwin.padding_left = padding_size;
};
/**
 * @method
 * @name GauceObjResize
 * @description desc
 * @param {string} a desc
 * @param {string} b desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.GauceObjResize = function(a, b) {
    var gw;
    var ew;
    if (array_grid.length == 0) {
        scwin.array_grid = [grd_Grid];
        scwin.setResizeGrid(scwin.array_grid);
    }
    for (var i = 0; i < array_grid.length; i++) {
        try {
            // GRID 처리
            array_grid[i].setBroadcast("false");
            gw = array_grid[i].style.getStyle("width");
            ew = a - parseInt(gw) - 35;
            array_grid[i].style.setGridWidth(parseInt(gw) + ew - scwin.padding_left);
            array_grid[i].setBroadcast("true");
        } catch (e) {


        }
    }

    // 공통엑셀저장버튼 처리
    try {
        // 상단공통패널부 처리
        __GROUPBOX_BACKGROUND__panel_1.style.setGridWidth(parseInt(gw) + ew);
    } catch (E) {

    }
    scwin.gOldWidthSize = frame.width;
};
